// Revenue anomaly self-healing module
// Detects revenue anomalies and auto-corrects pricing or triggers alerts

const axios = require('axios');
const { log } = require('../utils/logger');

class RevenueAnomalySelfHeal {
  constructor(config) {
    this.config = config;
    this.threshold = config.anomalyThreshold || 0.15; // 15% deviation
    this.checkInterval = config.checkInterval || 60000; // 1 minute
    this.intervalId = null;
  }

  start() {
    log('RevenueAnomalySelfHeal started');
    this.intervalId = setInterval(() => this.check(), this.checkInterval);
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  async check() {
    try {
      const currentRevenue = await this.fetchCurrentRevenue();
      const expectedRevenue = await this.fetchExpectedRevenue();
      if (expectedRevenue === 0) return;
      const deviation = Math.abs(currentRevenue - expectedRevenue) / expectedRevenue;
      if (deviation > this.threshold) {
        log(`Anomaly detected: deviation ${deviation.toFixed(2)}`);
        await this.selfHeal(currentRevenue, expectedRevenue);
      }
    } catch (err) {
      log(`RevenueAnomalySelfHeal error: ${err.message}`);
    }
  }

  async fetchCurrentRevenue() {
    // Placeholder: fetch from database or API
    const response = await axios.get('http://localhost:4000/api/revenue/current');
    return response.data.revenue;
  }

  async fetchExpectedRevenue() {
    // Placeholder: fetch from ML model or historical average
    const response = await axios.get('http://localhost:4000/api/revenue/expected');
    return response.data.revenue;
  }

  async selfHeal(currentRevenue, expectedRevenue) {
    // Auto-correct: adjust pricing by the deviation factor
    const adjustmentFactor = expectedRevenue / currentRevenue;
    log(`Adjusting pricing by factor ${adjustmentFactor.toFixed(4)}`);
    await axios.post('http://localhost:4000/api/pricing/adjust', { factor: adjustmentFactor });
    // Trigger alert
    await axios.post('http://localhost:4000/api/alerts', {
      type: 'revenue_anomaly',
      message: `Revenue anomaly detected. Current: ${currentRevenue}, Expected: ${expectedRevenue}. Auto-adjusted pricing.`
    });
  }
}

module.exports = RevenueAnomalySelfHeal;
